import React, { useEffect, useState }from 'react';
import Select from "react-select";
import '../styles/InformationForm.css';

const InformationForm = () => {
    return (
        <section>
            <div name="square" className="square">
                <form >
                    <br/>
                    <h2>Kontakt oplysninger</h2><br/>
                    <div className="form-control-lg" >
                        <div class="row justify-content-around">
                            <div class=" justify-content-around">

                            </div>
                            <input className="name" name="firstName mt-2" placeholder="Fornavn"/>
                            <input className="name" name="lastName mt-2" placeholder="Efternavn"/>
                            <input className="mail" name="mail" placeholder="Mail"/>
                            <input name="phoneNumber" placeholder="Tillefon nummer"/>
                        </div>
                    </div>

                    <br/><br/>
                    <h2>Levering</h2><br/>
                    <div className="CountrySelect align-self-center" name="CountrySelect">
                        <CountrySelect/>
                    </div>

                    <input name="areaCode" placeholder="Postnummer"/>
                    <input name="town" placeholder="By"/>
                    <input name="adres" placeholder="Adresse"/>
                </form>
            </div>
        </section>)
}

const CountrySelect = () => {
    const [countries, setCountries] = useState([]);
    const [selectedCountry, setSelectedCountry] = useState({});

    useEffect(() => {
        fetch(
            "https://valid.layercode.workers.dev/list/countries?format=select&flags=true&value=code"
        )
            .then((response) => response.json())
            .then((data) => {
                setCountries(data.countries);
                setSelectedCountry(data.userSelectValue);
            });
    }, []);
    return (
        <Select
            options={countries}
            value={selectedCountry}
            onChange={(selectedOption) => setSelectedCountry(selectedOption)}
        />
    );
};

export default InformationForm;
